!function(){"use strict";var e=window.IWACVis;e&&e.addTranslations&&(e.addTranslations("en",{"Loading scary terms":'Loading "scary" terms',"scary.title":'"Scary" terms in the IWAC collection',"scary.description":"How often words linked to radicalism and extremism appear in West African newspapers and Islamic periodicals between 1961 and 2025. Related words are grouped into families, so “terrorisme” and “terroriste” count together.","scary.cross_laicite":"These counts are anonymous totals. To see which individual articles pair this vocabulary with laïcité, go to the Laïcité dossier →","scary.view_mode":"View","scary.bar_race":"Bar chart race","scary.by_country":"By country","scary.global_view":"Global","scary.matrix":"Co-occurrence matrix","scary.country":"Country","scary.all_countries":"All countries","scary.chart_title":'"Scary" terms',"scary.country_chart_title":'"Scary" terms in {country}',"scary.global_chart_title":'"Scary" terms — global',"scary.matrix_chart_title":"Co-occurrence matrix — global","scary.matrix_country_chart_title":"Co-occurrence matrix — {country}","scary.matrix_description":"How often two of these term families appear together in the same article. The darker the cell, the more articles the pair shares. The diagonal is blank, since pairing a family with itself says nothing. Hover over a term label for its overall article count.","scary.matrix_empty":"No co-occurrences recorded for this slice.","scary.matrix_pair_tooltip":"{a} × {b}<br>{count} shared articles","scary.matrix_articles":"{count} articles","scary.total_articles":"Total articles","scary.term_families":"Term families","scary.term_variants":"Term variants","scary.total_occurrences":"Total occurrences","scary.term_definitions":"Term definitions","scary.top_term":"Top term","scary.play":"Play","scary.pause":"Pause","scary.previous":"Previous","scary.next":"Next","scary.reset":"Reset","scary.trends":"Trends","scary.trends_chart_title":'"Scary" terms over time',"scary.trends_country_chart_title":'"Scary" terms over time — {country}',"scary.trends_description":"Yearly occurrences of each term family. The dashed vertical markers flag historical events that help explain the visible spikes, and the shaded band marks the Algerian Civil War. Click a legend entry to isolate a family.","scary.show_events":"Show historical events","scary.events_list":"Historical events","scary.occurrences":"Occurrences","scary.wordcloud":"Word cloud","scary.wordcloud_chart_title":"Vocabulary of matching articles","scary.wordcloud_description":'The words that appear most often in the articles mentioning at least one of these terms, giving a quick view of the vocabulary that surrounds them. Each word is counted once per article. The "scary" terms themselves are left out, since they are what singled out this set of articles in the first place.',"scary.wordcloud_word_list":"Word list","scary.wordcloud_meta":"{articles} articles · {words} words shown","scary.by_family":"By family","scary.by_period":"By period","scary.word":"Word","scary.articles_col":"Articles","scary.map":"Map","scary.map_chart_title":"Places mentioned in matching articles","scary.map_description":"Where the coverage lands. Each bubble is a West African place, sized by how many of these articles were catalogued as being about it. The places come from the archive’s own location tags, added by cataloguers rather than read out of the article text, so a town goes unmarked if no article was filed under it. Filter by term family or by the newspaper’s country.","scary.map_family":"Term family","scary.all_families":"All families","scary.map_places_list":"Places list","scary.map_top_families":"Top families","scary.map_place":"Place"}),e.addTranslations("fr",{"Loading scary terms":"Chargement des termes « scary »","scary.title":"Termes « scary » dans la collection IWAC","scary.description":"Fréquence des mots liés à la radicalisation et à l’extrémisme dans les journaux et périodiques islamiques ouest-africains entre 1961 et 2025. Les mots apparentés sont regroupés en familles : « terrorisme » et « terroriste » comptent donc ensemble.","scary.cross_laicite":"Ces décomptes sont des totaux anonymes. Pour savoir quels articles associent ce vocabulaire à la laïcité, consulter le dossier Laïcité →","scary.view_mode":"Vue","scary.bar_race":"Course de barres","scary.by_country":"Par pays","scary.global_view":"Global","scary.matrix":"Matrice de co-occurrence","scary.country":"Pays","scary.all_countries":"Tous les pays","scary.chart_title":"Termes « scary »","scary.country_chart_title":"Termes « scary » — {country}","scary.global_chart_title":"Termes « scary » — global","scary.matrix_chart_title":"Matrice de co-occurrence — global","scary.matrix_country_chart_title":"Matrice de co-occurrence — {country}","scary.matrix_description":"À quelle fréquence deux de ces familles de termes apparaissent ensemble dans un même article. Plus la cellule est sombre, plus la paire partage d’articles. La diagonale est vide, car associer une famille à elle-même n’apporte rien. Survolez une étiquette pour voir son total d’articles.","scary.matrix_empty":"Aucune co-occurrence enregistrée pour cette sélection.","scary.matrix_pair_tooltip":"{a} × {b}<br>{count} articles partagés","scary.matrix_articles":"{count} articles","scary.total_articles":"Articles totaux","scary.term_families":"Familles de termes","scary.term_variants":"Variantes","scary.total_occurrences":"Occurrences totales","scary.term_definitions":"Définitions des termes","scary.top_term":"Terme principal","scary.play":"Lecture","scary.pause":"Pause","scary.previous":"Précédent","scary.next":"Suivant","scary.reset":"Réinitialiser","scary.trends":"Tendances","scary.trends_chart_title":"Termes « scary » au fil du temps","scary.trends_country_chart_title":"Termes « scary » au fil du temps — {country}","scary.trends_description":"Occurrences annuelles de chaque famille de termes. Les repères verticaux en pointillé signalent des événements historiques qui aident à expliquer les pics visibles, et la bande ombrée marque la guerre civile algérienne. Cliquez sur une entrée de la légende pour isoler une famille.","scary.show_events":"Afficher les événements historiques","scary.events_list":"Événements historiques","scary.occurrences":"Occurrences","scary.wordcloud":"Nuage de mots","scary.wordcloud_chart_title":"Vocabulaire des articles correspondants","scary.wordcloud_description":"Les mots qui reviennent le plus souvent dans les articles mentionnant au moins un de ces termes, ce qui donne un aperçu du vocabulaire qui les entoure. Chaque mot est compté une fois par article. Les termes « scary » eux-mêmes sont écartés, puisque ce sont eux qui ont isolé cet ensemble d’articles au départ.","scary.wordcloud_word_list":"Liste des mots","scary.wordcloud_meta":"{articles} articles · {words} mots affichés","scary.by_family":"Par famille","scary.by_period":"Par période","scary.word":"Mot","scary.articles_col":"Articles","scary.map":"Carte","scary.map_chart_title":"Lieux mentionnés dans les articles correspondants","scary.map_description":"Où se concentre la couverture. Chaque bulle est un lieu ouest-africain, dont la taille indique combien de ces articles ont été catalogués comme le concernant. Les lieux proviennent des étiquettes de lieu du fonds, ajoutées par les catalogueurs plutôt que relevées dans le texte des articles, de sorte qu’une localité reste non marquée si aucun article n’y a été rattaché. Filtrez par famille de termes ou par pays du journal.","scary.map_family":"Famille de termes","scary.all_families":"Toutes les familles","scary.map_places_list":"Liste des lieux","scary.map_top_families":"Familles principales","scary.map_place":"Lieu"}))}();